const HEADS_INSERT_GUARD: &str = "CREATE TRIGGER ops_mission_evidence_heads_insert_guard BEFORE INSERT ON ops_mission_evidence_heads WHEN NEW.revision!=1 OR NOT EXISTS(SELECT 1 FROM ops_mission_evidence_observations o JOIN ops_mission_evidence_bindings b ON b.request_id=o.binding_request_id WHERE o.request_id=NEW.observation_request_id AND o.binding_request_id=NEW.binding_request_id AND o.workspace_id=NEW.workspace_id AND o.plan_id=NEW.plan_id AND o.plan_revision=NEW.plan_revision AND o.revision=1 AND o.expected_head_revision=0 AND (SELECT COUNT(*) FROM ops_mission_evidence_observation_partitions p WHERE p.observation_request_id=o.request_id)=b.partition_count AND (SELECT COUNT(*) FROM ops_mission_evidence_observation_members m WHERE m.observation_request_id=o.request_id)=b.member_count) BEGIN SELECT RAISE(ABORT,'mission evidence head insert'); END";
const HEADS_UPDATE_GUARD: &str = "CREATE TRIGGER ops_mission_evidence_heads_update_guard BEFORE UPDATE ON ops_mission_evidence_heads WHEN NEW.binding_request_id!=OLD.binding_request_id OR NEW.workspace_id!=OLD.workspace_id OR NEW.plan_id!=OLD.plan_id OR NEW.plan_revision!=OLD.plan_revision OR NEW.revision!=OLD.revision+1 OR NOT EXISTS(SELECT 1 FROM ops_mission_evidence_observations o JOIN ops_mission_evidence_bindings b ON b.request_id=o.binding_request_id WHERE o.request_id=NEW.observation_request_id AND o.binding_request_id=NEW.binding_request_id AND o.workspace_id=NEW.workspace_id AND o.plan_id=NEW.plan_id AND o.plan_revision=NEW.plan_revision AND o.revision=NEW.revision AND o.expected_head_revision=OLD.revision AND (SELECT COUNT(*) FROM ops_mission_evidence_observation_partitions p WHERE p.observation_request_id=o.request_id)=b.partition_count AND (SELECT COUNT(*) FROM ops_mission_evidence_observation_members m WHERE m.observation_request_id=o.request_id)=b.member_count) OR EXISTS(SELECT 1 FROM ops_mission_evidence_observation_partitions np WHERE np.observation_request_id=NEW.observation_request_id AND NOT EXISTS(SELECT 1 FROM ops_mission_evidence_observation_partitions op WHERE op.observation_request_id=OLD.observation_request_id AND op.activity_id=np.activity_id AND op.t1_cut_id=np.t1_cut_id AND (np.review_source_high_water>op.review_source_high_water OR (np.review_source_high_water=op.review_source_high_water AND np.review_cut_id=op.review_cut_id AND np.review_t1_cut_id=op.review_t1_cut_id AND np.manifest_id=op.manifest_id AND np.manifest_revision=op.manifest_revision AND np.manifest_digest=op.manifest_digest AND np.deadline_ms=op.deadline_ms AND np.closed_at_ms=op.closed_at_ms AND np.t1_source_high_water=op.t1_source_high_water AND np.member_count=op.member_count)))) OR EXISTS(SELECT 1 FROM ops_mission_evidence_observation_partitions op WHERE op.observation_request_id=OLD.observation_request_id AND NOT EXISTS(SELECT 1 FROM ops_mission_evidence_observation_partitions np WHERE np.observation_request_id=NEW.observation_request_id AND np.activity_id=op.activity_id)) BEGIN SELECT RAISE(ABORT,'mission evidence head transition'); END";
const HEADS_IMMUTABLE_DELETE: &str = "CREATE TRIGGER ops_mission_evidence_heads_immutable_delete BEFORE DELETE ON ops_mission_evidence_heads BEGIN SELECT RAISE(ABORT,'mission evidence head retirement required'); END";

